import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn } from "node:child_process";

const BOT = "file://<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-inv-g4-1/bot.mjs";
const DAY = 24 * 3600 * 1000;
const dir = fs.mkdtempSync(path.join(os.tmpdir(), "bot-state-"));
process.env.STATE_DIR = path.join(dir, "nested", "state"); // missing parents on purpose
const { reserve } = await import(BOT);
const t0 = new Date("2026-10-23T10:00:00Z");
const at = (ms) => new Date(t0.getTime() + ms);

// 1. First 5 allowed across mixed channels, 6th refused
const chans = ["sms", "push", "chat", "sms", "push"];
for (let i = 0; i < 5; i++) {
  const r = await reserve("u1", chans[i], at(i * 1000));
  assert.equal(r.allowed, true); assert.equal(r.retryAt, null);
}
const denied = await reserve("u1", "chat", at(10_000));
assert.equal(denied.allowed, false);
assert.ok(denied.reason.length > 0);
console.log("reason:", denied.reason);
// oldest send was at t0+0; retry = t0 + DAY + 1
assert.equal(denied.retryAt.getTime(), t0.getTime() + DAY + 1);

// 2. Refused call counts nothing: still refused, same retryAt
const again = await reserve("u1", "sms", at(11_000));
assert.equal(again.allowed, false);
assert.equal(again.retryAt.getTime(), denied.retryAt.getTime());

// 3. Boundary: at retryAt - 1 refused, at retryAt allowed
const before = await reserve("u1", "sms", new Date(denied.retryAt.getTime() - 1));
assert.equal(before.allowed, false);
const at_ = await reserve("u1", "sms", denied.retryAt);
assert.equal(at_.allowed, true);
// window now: sends at 1s,2s,3s,4s, and retry instant. Next refusal retry = (1s)+DAY+1
const d2 = await reserve("u1", "push", at(20_000));
assert.equal(d2.allowed, false);
assert.equal(d2.retryAt.getTime(), t0.getTime() + 1000 + DAY + 1);

// 4. Isolation: other customer unaffected
for (let i = 0; i < 5; i++) assert.equal((await reserve("u2", "push", at(i))).allowed, true);
assert.equal((await reserve("u2", "push", at(6))).allowed, false);
assert.equal((await reserve("u3", "chat", at(7))).allowed, true);

// 5. Odd userId characters map to safe filenames
assert.equal((await reserve("../../etc/x y", "sms", at(0))).allowed, true);

// 6. Validation
await assert.rejects(reserve("", "sms", at(0)), TypeError);
await assert.rejects(reserve("u", "email", at(0)), TypeError);
await assert.rejects(reserve("u", "sms", new Date("nope")), TypeError);

// 7. Sliding window with a fresh customer: 5 sends at t0, then 24h later one more allowed
for (let i = 0; i < 5; i++) await reserve("u4", "sms", at(0));
assert.equal((await reserve("u4", "sms", at(DAY - 1))).allowed, false);
assert.equal((await reserve("u4", "sms", at(DAY + 1))).allowed, true);

// 8. Concurrency inside one process
const conc = await Promise.all(Array.from({ length: 20 }, (_, i) => reserve("u5", "sms", at(100 + i))));
assert.equal(conc.filter((r) => r.allowed).length, 5);

console.log("in-process tests passed");

// 9. Multiple OS processes hammering the same customer: exactly 5 allowed total
const worker = `
import { reserve } from ${JSON.stringify(BOT)};
const out = [];
for (let i = 0; i < 10; i++) out.push((await reserve("shared", "sms", new Date(${t0.getTime()} + i))).allowed);
console.log(JSON.stringify(out));`;
const wfile = path.join(dir, "worker.mjs");
fs.writeFileSync(wfile, worker);
const run = () => new Promise((resolve, reject) => {
  const p = spawn(process.execPath, [wfile], { env: process.env });
  let s = ""; let e = "";
  p.stdout.on("data", (d) => (s += d)); p.stderr.on("data", (d) => (e += d));
  p.on("close", (code) => code === 0 ? resolve(JSON.parse(s.trim())) : reject(new Error(e)));
});
const results = await Promise.all(Array.from({ length: 8 }, run));
const allowedTotal = results.flat().filter(Boolean).length;
console.log("allowed across 8 processes x 10 tries:", allowedTotal);
assert.equal(allowedTotal, 5);

// 10. Restart survival: a fresh process sees the 5 sends already made
const r = await (async () => {
  const p = spawn(process.execPath, ["-e", `import(${JSON.stringify(BOT)}).then(async m=>console.log(JSON.stringify(await m.reserve("shared","push",new Date(${t0.getTime()} + 500)))))`], { env: process.env });
  let s = ""; p.stdout.on("data", (d) => (s += d));
  await new Promise((res) => p.on("close", res));
  return JSON.parse(s.trim());
})();
assert.equal(r.allowed, false);
console.log("restart check:", r.allowed, r.retryAt);
console.log("ALL TESTS PASSED");
EOF
cd /tmp/bot-test && node test.mjs; echo "exit=$?"; find "$(node -e 'console.log(require("os").tmpdir())')" -maxdepth 1 -name 'bot-state-*' -newer /tmp/bot-test/test.mjs 2>/dev/null | head -1 | xargs -I{} sh -c 'find {} -type f | head; find {} -name "*.lock"'
